use aeterna_v1::scientific_runtime::{ScientificRuntime,UnifiedPost,RuntimeError};
use aeterna_v1::construction::{Config,Error};
use aeterna_v1::construction::autonomy::{ActionOffer,AutonomyPolicy};
use aeterna_v1::HumanProtectionEvidence;
fn safe(_:usize)->HumanProtectionEvidence {HumanProtectionEvidence{human_present:false,physical_effect_possible:false,predicted_harm_probability:0.0,hazard_confidence:1.0,emergency_stop:false}}
fn config()->Config{Config{minimum_training:32,journal_capacity:512,..Default::default()}}
fn make()->ScientificRuntime{ScientificRuntime::new_constructing(config(),AutonomyPolicy::default(),vec![0],"numeric-v1").unwrap()}
fn step(r:&mut ScientificRuntime){let x=r.construction_learner().unwrap().current()[0];r.step_constructing(None,&[ActionOffer{available:true,max_cost:1};2],safe,|a|Ok(UnifiedPost{observation:vec![x+a as i64],cost:1,reward:0.25})).unwrap();}
#[test] fn one_real_callback_and_one_factual_event(){let mut r=make();let mut calls=0;let s=r.step_constructing(None,&[ActionOffer{available:true,max_cost:1};2],safe,|a|{calls+=1;Ok(UnifiedPost{observation:vec![a as i64],cost:1,reward:0.0})}).unwrap();assert_eq!(calls,1);assert_eq!(s.event,1);assert_eq!(r.construction_learner().unwrap().records().len(),1);}
#[test] fn real_consequence_changes_existing_physical_weights(){let mut r=make();for _ in 0..12{step(&mut r);}let p=r.unified_report().unwrap();assert!(p.native_meta_observations>=12);assert!(p.native_weights.iter().any(|w|*w>0.0));assert_eq!(p.total_external_cost,12);}
#[test] fn checkpoint_restores_controller_and_learner_exactly(){let mut r=make();for _ in 0..12{step(&mut r);}let bytes=r.checkpoint_constructing().unwrap();let s=ScientificRuntime::from_constructing_checkpoint(&bytes).unwrap();assert_eq!(bytes,s.checkpoint_constructing().unwrap());}
#[test] fn resumed_decisions_and_checkpoints_match(){let mut a=make();for _ in 0..8{step(&mut a);}let mut b=ScientificRuntime::from_constructing_checkpoint(&a.checkpoint_constructing().unwrap()).unwrap();for _ in 0..8{step(&mut a);step(&mut b);assert_eq!(a.checkpoint_constructing().unwrap(),b.checkpoint_constructing().unwrap());}}
#[test] fn existing_native_route_cannot_be_a_second_commander(){let mut r=make();assert_eq!(r.propose(),Err(RuntimeError::ConstructionModeRequired));assert_eq!(r.propose_unified(),Err(RuntimeError::ConstructionModeRequired));assert_eq!(r.observe_external(&[0.0]),Err(RuntimeError::ConstructionModeRequired));}
#[test] fn emergency_is_retained_after_restore(){let mut r=make();let out=r.step_constructing(None,&[ActionOffer{available:true,max_cost:1};2],|a|{let mut h=safe(a);h.emergency_stop=true;h},|_|panic!("blocked"));assert!(matches!(out,Err(Error::Blocked)));let mut s=ScientificRuntime::from_constructing_checkpoint(&r.checkpoint_constructing().unwrap()).unwrap();assert!(s.emergency_latched());assert!(matches!(s.step_constructing(None,&[ActionOffer{available:true,max_cost:1};2],safe,|_|panic!("blocked after restart")),Err(Error::Blocked)));}
#[test] fn new_sensor_contract_preserves_controller_and_prior_experience(){let mut r=make();for _ in 0..8{step(&mut r);}let before=r.unified_report().unwrap();r.enter_constructing_domain("pixels-v1",config(),AutonomyPolicy::default(),vec![7]).unwrap();let after=r.unified_report().unwrap();assert_eq!(before.native_weights,after.native_weights);assert_eq!(after.archived_domains,["numeric-v1"]);assert_eq!(after.learner.events,0);assert_eq!(after.total_external_cost,8);let b=r.checkpoint_constructing().unwrap();assert_eq!(b,ScientificRuntime::from_constructing_checkpoint(&b).unwrap().checkpoint_constructing().unwrap());}
#[test] fn old_checkpoint_cannot_rewind_live_history(){let mut r=make();let old=r.checkpoint_constructing().unwrap();step(&mut r);assert_eq!(r.restore_constructing(&old),Err(Error::Stale));}
#[test] fn callback_fault_is_poisoned_and_not_retried(){let mut r=make();let e=r.step_constructing(None,&[ActionOffer{available:true,max_cost:1};2],safe,|_|Err(Error::Execution("unknown outcome".into())));assert!(e.is_err());assert!(r.emergency_latched());assert!(r.construction_learner().unwrap().report().poisoned);assert!(r.step_constructing(None,&[ActionOffer{available:true,max_cost:1};2],safe,|_|panic!("cannot retry unknown action")).is_err());}
#[test] fn freeze_preserves_weights_while_recording_real_outcomes(){let mut r=make();for _ in 0..8{step(&mut r);}r.freeze_constructing().unwrap();let w=r.unified_report().unwrap().native_weights;for _ in 0..8{step(&mut r);}assert_eq!(w,r.unified_report().unwrap().native_weights);assert_eq!(r.construction_learner().unwrap().records().len(),16);}
